<?php
 namespace Pterodactyl\Http\Controllers\Admin\Dezerx; use Illuminate\View\View; use Illuminate\Http\Request; use Illuminate\Http\RedirectResponse; use Prologue\Alerts\AlertsMessageBag; use Pterodactyl\Models\Dezerx\ImportHost; use Pterodactyl\Models\Dezerx\ImportCredential; use Pterodactyl\Http\Controllers\Controller; use Pterodactyl\Services\Dezerx\Importer\Policy; class ImporterController extends Controller { public function __construct(private readonly AlertsMessageBag $alert) { } public function index(): View { return view('admin.dezerx.importer.index', [ 'policy' => Policy::get(), 'saved' => ImportHost::query()->count(), 'credentials' => ImportCredential::query()->count(), 'people' => ImportHost::query()->distinct()->count('user_id'), 'hosts' => ImportHost::query() ->selectRaw('host, count(*) as total') ->groupBy('host') ->orderByDesc('total') ->limit(15) ->get(), 'maxPerUser' => ImportHost::MAX_PER_USER, ]); } public function update(Request $request): RedirectResponse { $data = $request->validate([ 'allowPrivate' => ['sometimes', 'boolean'], 'hosts' => ['nullable', 'string', 'max:4000'], 'maxFiles' => ['nullable', 'integer', 'min:0', 'max:1000000'], 'maxMegabytes' => ['nullable', 'integer', 'min:0', 'max:10000000'], 'maxConcurrent' => ['nullable', 'integer', 'min:0', 'max:1000'], 'maxPerDay' => ['nullable', 'integer', 'min:0', 'max:1000'], 'startPerMinute' => ['nullable', 'integer', 'min:1', 'max:1000'], ]); Policy::save([ 'allowPrivate' => (bool) ($data['allowPrivate'] ?? false), 'hosts' => (string) ($data['hosts'] ?? ''), 'maxFiles' => (int) ($data['maxFiles'] ?? 0), 'maxMegabytes' => (int) ($data['maxMegabytes'] ?? 0), 'maxConcurrent' => (int) ($data['maxConcurrent'] ?? 0), 'maxPerDay' => (int) ($data['maxPerDay'] ?? 0), 'startPerMinute' => (int) ($data['startPerMinute'] ?? 2), ]); $this->alert->success('Those import limits have been saved.')->flash(); return redirect()->route('admin.dezerx.importer'); } } 